#!/bin/bash
# OpenAI Ecosystem — BMBE + Standalone benchmarks on GPT-generated KB.
# KB: 18 diseases, ~160 features — likelihoods generated by GPT-5.4.
# Usage: bash experiments/llmkb/gpt_ecosystem.sh
set -euo pipefail
[ -f .env ] && source .env || true

PROFILES="data/cases/llmkb_gpt/plain/profiles.json"
DATA_DIR="data/kbs/llmkb_gpt"
OUTPUT="data/benchmark_results/llmkb"
N=50
PARALLEL=4
PATIENT_MODEL="gpt-5.4-nano"

mkdir -p "$OUTPUT"

# run NAME DOCTOR_MODEL [flags...]
run() {
  local name="$1" model="$2"; shift 2
  echo "=== GPT KB: ${name} ==="
  python3 scripts/core/benchmark_patientsim.py \
    --profiles "$PROFILES" --data-dir "$DATA_DIR" \
    "$@" --doctor-model "$model" \
    --patient-model "$PATIENT_MODEL" \
    --n $N --parallel $PARALLEL \
    --output "$OUTPUT/${name}"
}

run bmbe_gpt54nano gpt-5.4-nano --doctor-mode mobayes --force-max-turns
run sa_gpt54       gpt-5.4      --doctor-mode standalone
run sa_gpt54nano   gpt-5.4-nano --doctor-mode standalone
